tasks.test { useJUnitPlatform() }

// api/build.gradle.kts
plugins { id("acme.java-conventions"); `java-library` }
dependencies { api(project(":core")) }

// app/build.gradle.kts
plugins { id("acme.java-conventions"); application }
dependencies { implementation(project(":api")) }
application { mainClass = "com.acme.App" }
// $ ./gradlew :app:run      $ ./gradlew projects

// gradle.properties
// org.gradle.caching=true
// org.gradle.configuration-cache=true
// org.gradle.parallel=true

// build.gradle.kts: a custom cacheable task with declared inputs and outputs
abstract class Checksum : DefaultTask() {          // @CacheableTask in a plugin
    @get:InputFile @get:PathSensitive(PathSensitivity.RELATIVE)
    abstract val source: RegularFileProperty
    @get:OutputFile
    abstract val target: RegularFileProperty

    @TaskAction
    fun run() {
        val bytes = source.get().asFile.readBytes()
        val sha = java.security.MessageDigest.getInstance("SHA-256").digest(bytes)
        target.get().asFile.writeText(sha.joinToString("") { "%02x".format(it) })
    }
}

tasks.register<Checksum>("checksum") {
    source = layout.projectDirectory.file("README.md")
    target = layout.buildDirectory.file("README.sha256")
    outputs.cacheIf { true }    // script-defined types also need this; plugin classes use @CacheableTask alone
}
// 1st run: > Task :checksum        2nd run: > Task :checksum UP-TO-DATE
// after clean with caching on:    > Task :checksum FROM-CACHE

plugins { java }
repositories { mavenCentral() }

dependencies {
    implementation(platform("org.springframework.boot:spring-boot-dependencies:3.4.4"))
    implementation("org.springframework.boot:spring-boot-starter-web")   // version from the BOM

    implementation("org.apache.httpcomponents.client5:httpclient5:5.4.3") {
        exclude(group = "commons-logging", module = "commons-logging")
    }
    implementation("com.fasterxml.jackson.core:jackson-databind") {
        version { strictly("[2.18, 2.19[") }
    }
    constraints {
        implementation("org.yaml:snakeyaml:2.4") { because("fix CVE in transitive version") }
    }
}

configurations.all {
    resolutionStrategy {
        failOnVersionConflict()
        cacheChangingModulesFor(0, "seconds")
    }
}

dependencyLocking { lockAllConfigurations() }   // $ ./gradlew dependencies --write-locks
// $ ./gradlew dependencyInsight --dependency snakeyaml --configuration runtimeClasspath

concepts.body:
The `maven-publish` plugin publishes a project's artifacts to any Maven-compatible repository: Maven Central (via Sonatype), a company Nexus/Artifactory, GitHub Packages, or `mavenLocal()` (`~/.m2`) for local testing.

Configure a **publication** from the `java` component and one or more **repositories**:

```kotlin
publishing {
    publications { create<MavenPublication>("maven") { from(components["java"]) } }
    repositories { maven { url = uri("https://nexus.acme.com/repository/maven-releases") ; credentials { ... } } }
}
```

This generates tasks like `publishMavenPublicationToMavenRepository` and the aggregate `publish`, plus `publishToMavenLocal`.

The component maps Gradle's `api` dependencies to Maven `compile` scope and `implementation` to `runtime`, so consumers using Maven get a sensible POM. Gradle also publishes a `.module` file with richer metadata (variants, capabilities) that Gradle consumers use.

Add `java { withSourcesJar(); withJavadocJar() }` to publish source and Javadoc jars, which Maven Central requires, together with POM metadata (name, description, URL, license, developers, SCM) set through `pom { }`. The `signing` plugin signs artifacts with GPG; Central also requires it.

Use `group` and `version` for the coordinates; `-SNAPSHOT` versions go to snapshot repositories and can be republished. Never put credentials in the script: read them from `gradle.properties` in the home directory or environment variables (`providers.environmentVariable("NEXUS_TOKEN")`).

concepts.code:
plugins { `java-library`; `maven-publish`; signing }
group = "com.acme"
version = "1.2.0"
java { withSourcesJar(); withJavadocJar() }
publishing {
    publications {
        create<MavenPublication>("maven") {
            from(components["java"])
            pom {
                name = "acme-core"
                description = "Core utilities for ACME services"
                url = "https://github.com/acme/core"
                licenses { license { name = "Apache-2.0" } }
                developers { developer { id = "ada"; name = "Ada L." } }
                scm { url = "https://github.com/acme/core" }
            }
        }
    }
    repositories {
        maven {
            name = "nexus"
            url = uri("https://nexus.acme.com/repository/maven-releases")
            credentials(PasswordCredentials::class)   // nexusUsername / nexusPassword properties
        }
    }
}
signing { useGpgCmd(); sign(publishing.publications["maven"]) }
// $ ./gradlew publishToMavenLocal      $ ./gradlew publish

// build-logic/src/main/kotlin/com/acme/GreetingPlugin.kt
package com.acme

import org.gradle.api.*
import org.gradle.api.file.RegularFileProperty
import org.gradle.api.provider.Property
import org.gradle.api.tasks.*

abstract class GreetingExtension { abstract val message: Property<String> }

@CacheableTask
abstract class GreetTask : DefaultTask() {
    @get:Input abstract val message: Property<String>
    @get:OutputFile abstract val output: RegularFileProperty
    @TaskAction fun run() = output.get().asFile.writeText(message.get())
}
class GreetingPlugin : Plugin<Project> {
    override fun apply(project: Project) {
        val ext = project.extensions.create("greeting", GreetingExtension::class.java)
        ext.message.convention("Hello")                       // default, overridable
        project.tasks.register("greet", GreetTask::class.java) {
            it.message.set(ext.message.map { m -> "$m from ${project.name}" })   // lazy wiring
            it.output.set(project.layout.buildDirectory.file("greeting.txt"))
        }
    }
}
// consumer build.gradle.kts:  plugins { id("com.acme.greeting") }   greeting { message = "Hi" }
// $ ./gradlew greet && cat build/greeting.txt   -> Hi from app

