repositories { mavenCentral() }

java {
    toolchain { languageVersion = JavaLanguageVersion.of(21) }
    registerFeature("mongoSupport") {         // optional feature variant with its own deps
        usingSourceSet(sourceSets["main"])
    }
}

dependencies {
    "mongoSupportImplementation"("org.mongodb:mongodb-driver-sync:5.3.1")
    // consume a sibling's optional feature:
    implementation(project(":storage")) {
        capabilities { requireCapability("com.acme:storage-mongo-support") }
    }
}

// Force a specific target JVM attribute on a custom configuration
val tools by configurations.creating {
    attributes {
        attribute(Usage.USAGE_ATTRIBUTE, objects.named(Usage.JAVA_RUNTIME))
        attribute(TargetJvmVersion.TARGET_JVM_VERSION_ATTRIBUTE, 17)
    }
}
